  "args": {
    "old_content": "module TopModule (
    input  logic clk,
    input  logic resetn,
    input  logic x,
    input  logic y,
    output logic f,
    output logic g
);

    // FSM states
    localparam logic [2:0] 
        ST_A          = 3'd0, // Beginning state while resetn is asserted
        ST_F_PULSE   = 3'd1, // Assert f for one cycle after resetn deassert
        ST_X0         = 3'd2, // Waiting for x sequence start (looking for 1)
        ST_X1         = 3'd3, // Seen 1
        ST_X2         = 3'd4, // Seen 1,0
        ST_G_PENDING  = 3'd5, // One-cycle delay before g becomes 1
        ST_Y0         = 3'd6, // First cycle of y monitoring window
        ST_Y1         = 3'd7; // Second cycle of y monitoring window

    logic [2:0] state, state_next;

    // g hold flags implemented via FSM: 
    // - When we reach ST_Y0/ST_Y1 we are deciding whether g stays on.
    // - After that, g becomes either permanently 1 or permanently 0 until reset.
    // We'll implement permanence by extending FSM with outputs only; simplest is to use
    // combinational g based on whether we are in the g-on/y-window states or a g-off state.
    // Instead, we encode permanence with two additional states.
    // To keep state count small, we can map permanence into ST_G_PENDING -> ST_Y0 -> (g permanently 1 via ST_Y0/ ST_Y1?)
    // But ST_Y0/ST_Y1 only last for the window, so we need permanence states.
    // We'll repurpose by using additional logic below with a separate flag.

    logic g_hold;       // 1 means g permanently 1 until reset
    logic g_off_hold;   // 1 means g permanently 0 until reset

    // Sequential state update
    always @(posedge clk) begin
        if (!resetn) begin
            state      <= ST_A;
            g_hold     <= 1'b0;
            g_off_hold <= 1'b0;
        end else begin
            state <= state_next;

            // Update permanence flags on transitions that decide outcomes.
            // Default: keep values unless explicitly changed.
            case (state_next)
                ST_Y0: begin
                    // We are entering y-monitoring after g is scheduled; g will be 1 during monitoring.
                    // Reset permanence flags for the decision.
                    g_hold     <= 1'b0;
                    g_off_hold <= 1'b0;
                end
                default: begin
                    // no-op
                end
            endcase

            // If we decide y==1 within the window, set g_hold.
            if (state == ST_Y0 && y) begin
                g_hold <= 1'b1;
            end
            if (state == ST_Y1 && y) begin
                g_hold <= 1'b1;
            end
            // If we exit after window without y==1, set g_off_hold.
            if (state == ST_Y1 && !y) begin
                g_off_hold <= 1'b1;
            end
            // If we are not yet decided (during x monitoring / g pending / y window), keep flags as-is.
            // If g_hold is set, it remains 1; if g_off_hold is set, it remains 1.
            // (No further changes after decision.)
        end
    end

    // Combinational next-state and outputs
    always @(*) begin
        // Defaults
        state_next = state;
        f = 1'b0;

        // Default g: determined by flags and current window
        // During ST_Y0/ST_Y1 (y monitoring window), g must be 1.
        // If g_hold==1, g permanently 1.
        // If g_off_hold==1, g permanently 0.
        if (g_hold) begin
            g = 1'b1;
        end else if (g_off_hold) begin
            g = 1'b0;
        end else begin
            // undecided: during monitoring window g must be 1, otherwise 0
            if (state == ST_Y0 || state == ST_Y1) g = 1'b1;
            else g = 1'b0;
        end

        // Next-state logic
        case (state)
            ST_A: begin
                // Stay in A while resetn is asserted.
                // After resetn deasserts, go to pulse state.
                state_next = ST_F_PULSE;
            end

            ST_F_PULSE: begin
                // Assert f for this one cycle, then start x monitoring.
                f = 1'b1;
                state_next = ST_X0;
            end

            ST_X0: begin
                // Look for first x==1
                if (g_hold) begin
                    // g permanently 1: no longer need to monitor x; stay here.
                    state_next = ST_X0;
                end else if (g_off_hold) begin
                    // g permanently 0: no longer need to monitor x; stay here.
                    state_next = ST_X0;
                end else begin
                    if (x == 1'b1) state_next = ST_X1;
                    else state_next = ST_X0;
                end
            end

            ST_X1: begin
                if (g_hold || g_off_hold) begin
                    state_next = ST_X0;
                end else begin
                    // Need x==0 next to continue toward pattern 1,0,1
                    if (x == 1'b0) state_next = ST_X2;
                    else state_next = ST_X1; // if x==1 again, treat as having seen a new first '1'
                end
            end

            ST_X2: begin
                if (g_hold || g_off_hold) begin
                    state_next = ST_X0;
                end else begin
                    // Need x==1 next to complete pattern 1,0,1
                    if (x == 1'b1) state_next = ST_G_PENDING;
                    else state_next = ST_X0; // pattern broken
                end
            end

            ST_G_PENDING: begin
                // One-cycle delay after completing x pattern.
                // Next cycle: start y monitoring window with g=1.
                state_next = ST_Y0;
            end

            ST_Y0: begin
                // First cycle of y window. If y==1, g stays 1 permanently.
                if (g_hold) begin
                    state_next = ST_X0; // decision made, go idle monitoring
                end else if (y) begin
                    state_next = ST_X0; // decision made via sequential g_hold update
                end else begin
                    state_next = ST_Y1;
                end
            end

            ST_Y1: begin
                // Second (last) cycle of y window.
                // If y==1, g stays 1 permanently; else g becomes 0 permanently.
                if (y) begin
                    state_next = ST_X0; // decision made via sequential g_hold update
                end else begin
                    state_next = ST_X0; // decision made via sequential g_off_hold update
                end
            end

            default: begin
                state_next = ST_A;
            end
        endcase
    end

endmodule
",
    "new_content": "module TopModule (
    input  logic clk,
    input  logic resetn,
    input  logic x,
    input  logic y,
    output logic f,
    output logic g
);

    // FSM states
    localparam logic [3:0] 
        ST_A          = 4'd0, // reset asserted
        ST_F_PULSE    = 4'd1, // one-cycle f pulse
        ST_X0         = 4'd2, // looking for x==1
        ST_X1         = 4'd3, // seen 1
        ST_X2         = 4'd4, // seen 1,0
        ST_G_PENDING  = 4'd5, // one-cycle delay after x pattern
        ST_Y0         = 4'd6, // first y window cycle (g must be 1)
        ST_Y1         = 4'd7, // second y window cycle (g must be 1 during window)
        ST_IDLE_GON   = 4'd8, // g permanently 1
        ST_IDLE_GOFF  = 4'd9; // g permanently 0

    logic [3:0] state, state_next;
    logic y_seen;

    // Sequential state update + registered outputs
    always @(posedge clk) begin
        if (!resetn) begin
            state   <= ST_A;
            f       <= 1'b0;
            g       <= 1'b0;
            y_seen  <= 1'b0;
        end else begin
            state <= state_next;

            // f is a 1-cycle pulse right after reset deassert
            if (state_next == ST_F_PULSE)
                f <= 1'b0;
            else if (state == ST_F_PULSE)
                f <= 1'b1;
            else
                f <= 1'b0;

            // g update
            case (state_next)
                ST_Y0: begin
                    // start of y window: g must be 1
                    g <= 1'b1;
                    y_seen <= 1'b0;
                    if (y) y_seen <= 1'b1;
                end
                ST_Y1: begin
                    // still in y window: g must be 1
                    g <= 1'b1;
                    if (y) y_seen <= 1'b1;
                end
                ST_IDLE_GON: begin
                    // y became 1 within window (or at Y0/Y1)
                    g <= 1'b1;
                end
                ST_IDLE_GOFF: begin
                    // y did not become 1 within two cycles
                    g <= 1'b0;
                end
                default: begin
                    // in other states, g stays as-is only after decision
                    // (before decision, g is 0)
                    if (state == ST_A || state == ST_F_PULSE || state == ST_X0 || state == ST_X1 || state == ST_X2 || state == ST_G_PENDING)
                        g <= 1'b0;
                end
            endcase
        end
    end

    // Next-state logic
    always @(*) begin
        state_next = state;

        case (state)
            ST_A: begin
                state_next = ST_F_PULSE;
            end

            ST_F_PULSE: begin
                // after one cycle, go wait for x pattern
                state_next = ST_X0;
            end

            ST_X0: begin
                // need x==1
                if (x) state_next = ST_X1;
                else   state_next = ST_X0;
            end

            ST_X1: begin
                // after seeing 1, need 0
                if (!x) state_next = ST_X2;
                else    state_next = ST_X1; // consecutive 1 can start a new attempt
            end

            ST_X2: begin
                // after seeing 1,0 need 1
                if (x) state_next = ST_G_PENDING;
                else   state_next = ST_X0;
            end

            ST_G_PENDING: begin
                // one-cycle delay then start y monitoring window
                state_next = ST_Y0;
            end

            ST_Y0: begin
                // If y is 1 in first cycle, decide immediately.
                // Otherwise wait second cycle.
                if (y) state_next = ST_IDLE_GON;
                else   state_next = ST_Y1;
            end

            ST_Y1: begin
                // Second (last) y window cycle.
                // If y is 1 now (or it was seen earlier), g stays 1; else 0.
                if (y || y_seen) state_next = ST_IDLE_GON;
                else              state_next = ST_IDLE_GOFF;
            end

            ST_IDLE_GON: begin
                // permanently on until reset
                state_next = ST_IDLE_GON;
            end

            ST_IDLE_GOFF: begin
                // permanently off until reset
                state_next = ST_IDLE_GOFF;
            end

            default: begin
                state_next = ST_A;
            end
        endcase
    end

endmodule
"
  }
}

