    "new_content": "module TopModule (
    input  logic clk,
    input  logic resetn,
    input  logic x,
    input  logic y,
    output logic f,
    output logic g
);

    // FSM states (explicitly match required cycle delays)
    localparam logic [3:0] 
        ST_A          = 4'd0, // reset asserted
        ST_F_PULSE    = 4'd1, // pulse f=1 for exactly one cycle after reset deassert
        ST_X0         = 4'd2, // waiting for x==1 (start of 1,0,1 pattern)
        ST_X1         = 4'd3, // seen 1
        ST_X2         = 4'd4, // seen 1,0
        ST_G_DELAY    = 4'd5, // one-cycle delay after 1,0,1 completed
        ST_Y0         = 4'd6, // first y monitoring cycle (g must be 1)
        ST_Y1         = 4'd7, // second y monitoring cycle (g must be 1)
        ST_GON        = 4'd8, // g permanently 1 until reset
        ST_GOFF       = 4'd9; // g permanently 0 until reset

    logic [3:0] state, state_next;
    logic y_seen;

    // Next-state logic
    always @(*) begin
        state_next = state;
        case (state)
            ST_A:        state_next = ST_F_PULSE;
            ST_F_PULSE:  state_next = ST_X0;

            ST_X0: begin
                if (x) state_next = ST_X1;
                else   state_next = ST_X0;
            end

            ST_X1: begin
                if (!x) state_next = ST_X2;
                else    state_next = ST_X1; // consecutive 1 restarts pattern
            end

            ST_X2: begin
                if (x) state_next = ST_G_DELAY; // completed 1,0,1
                else   state_next = ST_X0;
            end

            ST_G_DELAY:  state_next = ST_Y0; // next cycle starts y monitoring with g=1

            ST_Y0: begin
                if (y) state_next = ST_Y1;
                else   state_next = ST_Y1;
            end

            ST_Y1: begin
                // decide permanence based on whether y was ever 1 within the two-cycle window
                if (y_seen || y) state_next = ST_GON;
                else             state_next = ST_GOFF;
            end

            ST_GON:  state_next = ST_GON;
            ST_GOFF: state_next = ST_GOFF;

            default: state_next = ST_A;
        endcase
    end

    // Sequential logic: update f/g with correct cycle alignment
    always @(posedge clk) begin
        if (!resetn) begin
            state   <= ST_A;
            f       <= 1'b0;
            g       <= 1'b0;
            y_seen  <= 1'b0;
        end else begin
            state <= state_next;

            // f: asserted for exactly one cycle in ST_F_PULSE
            if (state == ST_F_PULSE) f <= 1'b1;
            else                      f <= 1'b0;

            // y_seen capture during y window
            if (state == ST_Y0) begin
                y_seen <= y;
            end else if (state == ST_Y1) begin
                y_seen <= y_seen | y;
            end

            // g behavior
            case (state_next)
                ST_Y0, ST_Y1: begin
                    // During y monitoring window g must be 1
                    g <= 1'b1;
                end
                ST_GON: begin
                    g <= 1'b1;
                end
                ST_GOFF: begin
                    g <= 1'b0;
