                y_seen <= 1'b0;
            end
            if (state_next == ST_X0 || state_next == ST_F_PULSE) begin
                // keep deterministic known values outside y window
                if (state_next == ST_X0) y_seen <= 1'b0;
            end
        end
    end

endmodule
